     */
    func resumeTransfer(id: String) throws 
    
    /**
     * Id of the default local root (what the browser opens first).
     */
    func rootId()  -> String
    
    /**
     * 扫描主体在模块级自由函数 [`index_subtree_on`] 里（uniffi 的 export
