    func search(query: String, limit: UInt32) throws  -> [Entry]
    
    /**
     * 枚举 SMB 服务器上可访问的共享名（UI「列出共享」用；需要可达 + 凭据有效）。
     */
    func smbListShares(host: String, port: UInt32, username: String, password: String) throws  -> [String]
    
    /**
