    func startShare(ids: [String]) throws  -> ShareInfo
    
    func startTransfer(sources: [String], destDir: String, conflict: ConflictPolicy, isMove: Bool) throws  -> String
    
    func stat(id: String) throws  -> Entry
    
    func stopLocalSend() 
    
    /**
