/**
 * Immutable progress snapshot, polled by the UI.
 */
public struct TransferSnapshot: Equatable, Hashable {
    public var id: String
    public var state: TransferState
    public var bytesDone: UInt64
    public var bytesTotal: UInt64
    public var filesDone: UInt64
    public var filesTotal: UInt64
    public var current: String?
    public var error: String?
    /**
     * 任务创建（开始）时间，epoch 毫秒。
     */
    public var startedAtMs: Int64
    /**
     * 结束时间（完成/失败/取消），未结束为 None。
     */
    public var finishedAtMs: Int64?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(id: String, state: TransferState, bytesDone: UInt64, bytesTotal: UInt64, filesDone: UInt64, filesTotal: UInt64, current: String?, error: String?, 
        /**
         * 任务创建（开始）时间，epoch 毫秒。
         */startedAtMs: Int64, 
        /**
         * 结束时间（完成/失败/取消），未结束为 None。
         */finishedAtMs: Int64?) {
        self.id = id
        self.state = state
        self.bytesDone = bytesDone
        self.bytesTotal = bytesTotal
        self.filesDone = filesDone
        self.filesTotal = filesTotal
        self.current = current
        self.error = error
        self.startedAtMs = startedAtMs
        self.finishedAtMs = finishedAtMs
    }

    

    
}

#if compiler(>=6)
extension TransferSnapshot: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeTransferSnapshot: FfiConverterRustBuffer {
    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> TransferSnapshot {
        return
            try TransferSnapshot(
                id: FfiConverterString.read(from: &buf), 
                state: FfiConverterTypeTransferState.read(from: &buf), 
                bytesDone: FfiConverterUInt64.read(from: &buf), 
                bytesTotal: FfiConverterUInt64.read(from: &buf), 
                filesDone: FfiConverterUInt64.read(from: &buf), 
                filesTotal: FfiConverterUInt64.read(from: &buf), 
                current: FfiConverterOptionString.read(from: &buf), 
                error: FfiConverterOptionString.read(from: &buf), 
                startedAtMs: FfiConverterInt64.read(from: &buf), 
                finishedAtMs: FfiConverterOptionInt64.read(from: &buf)
        )
    }

    public static func write(_ value: TransferSnapshot, into buf: inout [UInt8]) {
        FfiConverterString.write(value.id, into: &buf)
        FfiConverterTypeTransferState.write(value.state, into: &buf)
        FfiConverterUInt64.write(value.bytesDone, into: &buf)
        FfiConverterUInt64.write(value.bytesTotal, into: &buf)
        FfiConverterUInt64.write(value.filesDone, into: &buf)
        FfiConverterUInt64.write(value.filesTotal, into: &buf)
        FfiConverterOptionString.write(value.current, into: &buf)
        FfiConverterOptionString.write(value.error, into: &buf)
        FfiConverterInt64.write(value.startedAtMs, into: &buf)
        FfiConverterOptionInt64.write(value.finishedAtMs, into: &buf)
    }
}


