    )
    case Unsupported(detail: String
    )
    case Network(detail: String
    )
    case InvalidName(detail: String
    )
    case Io(detail: String
    )
    case Cancelled(detail: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

