    typealias SwiftType = SfError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SfError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .NotFound(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 2: return .PermissionDenied(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 3: return .AlreadyExists(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Unsupported(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Network(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 6: return .InvalidName(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 7: return .Io(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 8: return .Cancelled(
            detail: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: SfError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .NotFound(detail):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .PermissionDenied(detail):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .AlreadyExists(detail):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .Unsupported(detail):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .Network(detail):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .InvalidName(detail):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .Io(detail):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .Cancelled(detail):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(detail, into: &buf)
            
        }
    }
}


